DECLARE @RejectId BIGINT, @Key NVARCHAR(200), @Reason NVARCHAR(50);
DECLARE dq_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT r.RejectedRowId, r.CustomerCode, r.RejectReasonCode
    FROM [err].[RejectedCustomer] AS r
    WHERE r.BatchId = ? AND r.LoggedToControl = 0;
OPEN dq_cur;
FETCH NEXT FROM dq_cur INTO @RejectId, @Key, @Reason;
WHILE @@FETCH_STATUS = 0
BEGIN
    EXEC etl.usp_LogRejectedRecord @PackageExecutionId = ?, @BatchId = ?, @SourceSystemCode = ?, @ObjectName = N'stg.Customer', @BusinessKey = @Key, @RejectReasonCode = @Reason, @RejectStage = N'Quality';
    UPDATE [err].[RejectedCustomer] SET LoggedToControl = 1 WHERE RejectedRowId = @RejectId;
    FETCH NEXT FROM dq_cur INTO @RejectId, @Key, @Reason;
END
CLOSE dq_cur;
DEALLOCATE dq_cur;

