DECLARE @RejectId BIGINT, @Key NVARCHAR(200), @Reason NVARCHAR(50);
DECLARE dq_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT r.RejectedRowId, r.BusinessKey, r.RejectReasonCode
    FROM [err].[RejectedConstraintViolation] AS r
    WHERE r.BatchId = ? AND r.LoggedToControl = 0;
OPEN dq_cur;
FETCH NEXT FROM dq_cur INTO @RejectId, @Key, @Reason;
WHILE @@FETCH_STATUS = 0
BEGIN
    EXEC etl.usp_LogRejectedRecord @PackageExecutionId = ?, @BatchId = ?, @SourceSystemCode = ?, @ObjectName = N'etl.DataQualityResult', @BusinessKey = @Key, @RejectReasonCode = @Reason, @RejectStage = N'RuleEngine';
    UPDATE [err].[RejectedConstraintViolation] SET LoggedToControl = 1 WHERE RejectedRowId = @RejectId;
    FETCH NEXT FROM dq_cur INTO @RejectId, @Key, @Reason;
END
CLOSE dq_cur;
DEALLOCATE dq_cur;

DECLARE @RuleId INT, @RuleCode NVARCHAR(30), @ObjectName NVARCHAR(200), @RuleExpression NVARCHAR(1000), @Sql NVARCHAR(MAX), @Measure DECIMAL(18,4);
DECLARE rule_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT DataQualityRuleId, RuleCode, ObjectName, RuleExpression
    FROM etl.DataQualityRule WHERE IsActive = 1 ORDER BY RuleGroupCode, RuleCode;
OPEN rule_cur;
FETCH NEXT FROM rule_cur INTO @RuleId, @RuleCode, @ObjectName, @RuleExpression;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @Sql = N'SELECT @Out = CAST(COUNT_BIG(*) AS DECIMAL(18,4)) FROM ' + @ObjectName +
               N' WHERE ' + @RuleExpression + N';';
    BEGIN TRY
        EXEC sp_executesql @Sql, N'@Out DECIMAL(18,4) OUTPUT', @Out = @Measure OUTPUT;
    END TRY
    BEGIN CATCH
        SET @Measure = -1;
    END CATCH
    INSERT INTO etl.DataQualityResult
        (BatchId, PackageExecutionId, ObjectName, RuleCode, MeasuredValue, EvaluatedAtUtc)
    VALUES (?, ?, @ObjectName, @RuleCode, @Measure, SYSUTCDATETIME());
    FETCH NEXT FROM rule_cur INTO @RuleId, @RuleCode, @ObjectName, @RuleExpression;
END
CLOSE rule_cur;
DEALLOCATE rule_cur;

