DECLARE @sql nvarchar(max) = N'';
DECLARE @Period nvarchar(7) = ?;
DECLARE @Scope nvarchar(10) = ?;
SELECT @sql = @sql + N'UPDATE etl.Configuration SET ConfigurationValue = N''Closed'' WHERE ConfigurationKey = N''Finance.PeriodStatus.' + LedgerCode + N''';' + CHAR(13)
FROM   (SELECT DISTINCT LedgerCode FROM Fact.[GL Posting] WHERE [Accounting Period] = @Period) AS l
WHERE  @Scope = N'ALL' OR l.LedgerCode = @Scope;
EXEC sp_executesql @sql;

DECLARE @LedgerCode nvarchar(10), @BucketCode nvarchar(6);
DECLARE aging_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT DISTINCT LedgerCode, AgingBucketCode FROM work.ApAgingStaging ORDER BY LedgerCode, AgingBucketCode;
OPEN aging_cur;
FETCH NEXT FROM aging_cur INTO @LedgerCode, @BucketCode;
WHILE @@FETCH_STATUS = 0
BEGIN
    EXEC Integration.usp_RefreshApAgingSummary @LedgerCode = @LedgerCode, @BucketCode = @BucketCode;
    FETCH NEXT FROM aging_cur INTO @LedgerCode, @BucketCode;
END
CLOSE aging_cur;
DEALLOCATE aging_cur;

DECLARE @RuleId int, @Driver nvarchar(20), @Source nvarchar(10), @Basis nvarchar(20);
DECLARE rule_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT AllocationRuleId, DriverCode, SourceCostCentreCode, AllocationBasisCode
    FROM   stg.CostAllocationRule
    WHERE  RuleSetCode = ? AND IsActive = 1
    ORDER BY RuleSequence;
OPEN rule_cur;
FETCH NEXT FROM rule_cur INTO @RuleId, @Driver, @Source, @Basis;
WHILE @@FETCH_STATUS = 0
BEGIN
    INSERT INTO work.CostAllocationResult
        (AllocationRuleId, SourceCostCentreCode, TargetCostCentreCode, DriverCode,
         AllocatedAmount, AccountingPeriod)
    SELECT  @RuleId, @Source, t.TargetCostCentreCode, @Driver,
            src.PoolAmount * (t.DriverValue / NULLIF(SUM(t.DriverValue) OVER (), 0)),
            ?
    FROM    stg.CostAllocationTarget AS t
    CROSS APPLY (SELECT SUM(Amount) AS PoolAmount
                 FROM   stg.CostCentreBalance
                 WHERE  CostCentreCode = @Source AND AccountingPeriod = ?) AS src
    WHERE   t.AllocationRuleId = @RuleId;
    FETCH NEXT FROM rule_cur INTO @RuleId, @Driver, @Source, @Basis;
END
CLOSE rule_cur;
DEALLOCATE rule_cur;

DECLARE @CycleCountId int, @StockItemId int, @Site nvarchar(10), @Qty int, @Value decimal(18,2);
DECLARE variance_cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT CycleCountId, StockItemId, WarehouseSiteCode, VarianceQuantity, VarianceValue
    FROM   work.CycleCountVariance
    WHERE  CountStatusCode = N'AUTO'
    ORDER BY CountedAtUtc;
OPEN variance_cur;
FETCH NEXT FROM variance_cur INTO @CycleCountId, @StockItemId, @Site, @Qty, @Value;
WHILE @@FETCH_STATUS = 0
BEGIN
    EXEC Integration.usp_PostInventoryAdjustment
         @StockItemId = @StockItemId, @WarehouseSiteCode = @Site,
         @AdjustmentQuantity = @Qty, @AdjustmentValue = @Value,
         @MovementReasonCode = N'CYCLECOUNT', @SourceReference = @CycleCountId;
    FETCH NEXT FROM variance_cur INTO @CycleCountId, @StockItemId, @Site, @Qty, @Value;
END
CLOSE variance_cur;
DEALLOCATE variance_cur;

DECLARE @SchemaName sysname, @TableName sysname, @DateColumn sysname,
        @CutoffDate date, @Sql nvarchar(max), @Chunk int = ?, @Deleted int = 1,
        @DryRun bit = ?;
DECLARE PurgeCursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT SchemaName, TableName, LoadDateColumn, CutoffDate
    FROM   work.StagingPurgePlan ORDER BY EstimatedRows DESC;
OPEN PurgeCursor;
FETCH NEXT FROM PurgeCursor INTO @SchemaName, @TableName, @DateColumn, @CutoffDate;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @Deleted = 1;
    WHILE @Deleted > 0
    BEGIN
        SET @Sql = N'DELETE TOP (' + CAST(@Chunk AS nvarchar(20)) + N') FROM '
                 + QUOTENAME(@SchemaName) + N'.' + QUOTENAME(@TableName)
                 + N' WHERE ' + QUOTENAME(@DateColumn) + N' < @Cutoff;';
        IF @DryRun = 1 BREAK;
        EXEC sp_executesql @Sql, N'@Cutoff date', @Cutoff = @CutoffDate;
        SET @Deleted = @@ROWCOUNT;
        INSERT INTO etl.PurgeAudit
            (BatchId, SchemaName, TableName, CutoffDate, RowsDeleted, PurgedAtUtc)
        VALUES (NULL, @SchemaName, @TableName, @CutoffDate, @Deleted, SYSUTCDATETIME());
    END
    FETCH NEXT FROM PurgeCursor INTO @SchemaName, @TableName, @DateColumn, @CutoffDate;
END
CLOSE PurgeCursor; DEALLOCATE PurgeCursor;

DECLARE @Schema sysname, @Table sysname, @Index sysname, @Action nvarchar(30),
        @Sql nvarchar(max), @Online bit = ?, @Deadline datetime2(0);
SET @Deadline = DATEADD(MINUTE, ?, SYSUTCDATETIME());
DECLARE IndexCursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT SchemaName, TableName, IndexName, PlannedAction
    FROM   work.IndexMaintenancePlan
    WHERE  IndexTypeCode = N'ROWSTORE' AND PlannedAction <> N'NONE'
    ORDER BY PageCount DESC;
OPEN IndexCursor;
FETCH NEXT FROM IndexCursor INTO @Schema, @Table, @Index, @Action;
WHILE @@FETCH_STATUS = 0 AND SYSUTCDATETIME() < @Deadline
BEGIN
    SET @Sql = N'ALTER INDEX ' + QUOTENAME(@Index) + N' ON '
             + QUOTENAME(@Schema) + N'.' + QUOTENAME(@Table)
             + CASE WHEN @Action = N'REBUILD'
                    THEN N' REBUILD WITH (ONLINE = '
                         + CASE WHEN @Online = 1 THEN N'ON' ELSE N'OFF' END
                         + N', SORT_IN_TEMPDB = ON);'
                    ELSE N' REORGANIZE;' END;
    BEGIN TRY
        EXEC sp_executesql @Sql;
        INSERT INTO etl.MaintenanceLog (TaskName, DetailText, RecordedAtUtc)
        VALUES (N'MNT_Rebuild_Indexes', @Sql, SYSUTCDATETIME());
    END TRY
    BEGIN CATCH
        INSERT INTO etl.MaintenanceLog (TaskName, DetailText, RecordedAtUtc)
        VALUES (N'MNT_Rebuild_Indexes',
                CONCAT(N'FAILED: ', @Sql, N' -> ', ERROR_MESSAGE()), SYSUTCDATETIME());
    END CATCH
    FETCH NEXT FROM IndexCursor INTO @Schema, @Table, @Index, @Action;
END
CLOSE IndexCursor; DEALLOCATE IndexCursor;

DECLARE @Schema sysname, @Table sysname, @Stat sysname, @Mode nvarchar(20),
        @Sample int = ?, @Sql nvarchar(max);
DECLARE StatsCursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT SchemaName, TableName, StatisticsName, RefreshMode
    FROM   work.StatisticsRefreshPlan ORDER BY ModifiedRowCount DESC;
OPEN StatsCursor;
FETCH NEXT FROM StatsCursor INTO @Schema, @Table, @Stat, @Mode;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @Sql = N'UPDATE STATISTICS ' + QUOTENAME(@Schema) + N'.' + QUOTENAME(@Table)
             + N' ' + QUOTENAME(@Stat)
             + CASE WHEN @Mode = N'FULLSCAN' THEN N' WITH FULLSCAN;'
                    ELSE N' WITH SAMPLE ' + CAST(@Sample AS nvarchar(10))
                         + N' PERCENT;' END;
